import { lazy, Suspense } from "react";

// одна функция загрузки на оба случая
const loadSettings = () => import("./routes/Settings");
const Settings = lazy(loadSettings);

function NavLink() {
  // prefetch: начинаем качать чанк при наведении, до клика
  return <a href="/settings" onMouseEnter={loadSettings}>Настройки</a>;
}

function SettingsRoute() {
  return (
    <Suspense fallback={<p>Loading…</p>}>
      <Settings />
    </Suspense>
  );
}

